export async function runMigrations(
  databasePath: string = process.env.TASKFLOW_DB_PATH ?? DEFAULT_DB_PATH,
): Promise<void> {
  const absolute = resolve(process.cwd(), databasePath);
  mkdirSync(dirname(absolute), { recursive: true });

  const sqlite = new Database(absolute);
  sqlite.pragma("journal_mode = WAL");

  try {
    for (const statement of readMigrationStatements()) {
      sqlite.exec(statement);
    }

    // Existing databases can predate the nullable project association. The
    // fallback schema creates it directly, while this keeps upgraded installs
    // compatible when their migration set does not contain the column yet.
    const notificationColumns = sqlite
      .prepare("PRAGMA table_info(notifications)")
      .all() as Array<{ name: string }>;
    if (!notificationColumns.some((column) => column.name === "project_id")) {
      sqlite.exec("ALTER TABLE notifications ADD COLUMN project_id TEXT");
    }
  } finally {
    sqlite.close();
  }
}

